DECLARE @watermark_to VARCHAR(50) = NULL;

IF UPPER(@load_type) <> 'FULL'
   AND @watermark_column IS NOT NULL
   AND @target_schema IS NOT NULL
   AND @target_table IS NOT NULL
BEGIN
    DECLARE @sql NVARCHAR(MAX) = N'
        SELECT @res = CAST(MAX(' + QUOTENAME(@watermark_column) + N') AS NVARCHAR(50))
        FROM ' + QUOTENAME(@target_schema) + N'.' + QUOTENAME(@target_table);

    EXEC sp_executesql @sql, N'@res VARCHAR(50) OUTPUT', @res = @watermark_to OUTPUT;
END;

